    usedList = readfile(USED_FILE)
end

local alreadyActivated = false
for id in string.gmatch(usedList, "[^\n]+") do
    if id == USER_ID then
        alreadyActivated = true
        break
    end
end

-- 已激活过：静默跳过开场动画（不黑屏、不提示），直接放行执行主脚本
