local bgm
task.spawn(function()
    if not getcustomasset then return end
    local old = SoundService:FindFirstChild("WXHUB_BGM")
    if old then old:Destroy() end

    bgm = Instance.new("Sound")
    bgm.Name = "WXHUB_BGM"
    bgm.Volume = VOLUME
    bgm.Looped = LOOPED
    bgm.Parent = SoundService

    local cached = isfile(FILE_NAME)
    if not cached then
        local r = request({ Url = BG_MUSIC_URL, Method = "GET" })
        if r and r.Body and #r.Body > 1000 then
            writefile(FILE_NAME, r.Body)
        else
            bgm:Destroy()
            bgm = nil
            return
        end
    end
    bgm.SoundId = getcustomasset(FILE_NAME)
    bgm:Play()
end)

