tw(barFill, TweenInfo.new(6, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Size = UDim2.fromScale(0.7, 1) })
task.wait(6.6)
tw(barFill, TweenInfo.new(2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Size = UDim2.fromScale(1, 1) })
task.wait(greetDuration - 6.6 + 1.5)

tw(flash, FLASH, { BackgroundTransparency = 0 })
task.wait(0.12)
logoHolder.Visible = false
subtitle.Visible = false
badge.Visible = false
leftCol.Visible = false
rightCol.Visible = false
barBack.Visible = false
starLayer.Visible = false
tw(flash, FLASH, { BackgroundTransparency = 1 })

tw(endLabel, BOUNCE, { TextTransparency = 0 })
tw(endStroke, BOUNCE, { Transparency = 0 })

if FADE_BGM and bgm then
    task.spawn(function()
        tw(bgm, TweenInfo.new(2.5, Enum.EasingStyle.Linear), { Volume = 0 })
    end)
end

for _ = 1, 2 do
    task.wait(1.0)
    tw(endStroke, SLOW, { Thickness = 7 })
    task.wait(0.2)
    tw(endStroke, SLOW, { Thickness = 4 })
end
task.wait(0.5)

tw(endLabel, SMOOTH, { TextTransparency = 1 })
tw(endStroke, SMOOTH, { Transparency = 1 })
tw(back, SMOOTH, { BackgroundTransparency = 1 })
task.wait(1.0)

if bgm and not LOOPED then
    bgm:Stop()
    bgm:Destroy()
end
gui:Destroy()
end

