-- ===== 状态本地持久化：列表小框里改过的状态存到文件，下次执行自动恢复（UI存档 > Extra > 主表）=====
local SERVER_STATUS_FILE = "WXHUB_ServerStatus.json"
local ServerStatusUserSet = {}
pcall(function()
    if isfile and readfile and isfile(SERVER_STATUS_FILE) then
        local raw = readfile(SERVER_STATUS_FILE)
        local okJ, data = pcall(function()
            return game:GetService("HttpService"):JSONDecode(raw)
        end)
        if okJ and type(data) == "table" then
            for k, v in pairs(data) do
                if type(k) == "string" and (v == "red" or v == "yellow" or v == "green") then
                    ServerStatusUserSet[k] = v
                    ServerStatusMap[k] = v
                end
            end
        end
    end
end)

local function SaveServerStatus()
    pcall(function()
        if writefile then
            writefile(SERVER_STATUS_FILE, game:GetService("HttpService"):JSONEncode(ServerStatusUserSet))
        end
    end)
end

local TweenService = game:GetService("TweenService")
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")

local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local function IsMobile()
    return UserInputService.TouchEnabled and not UserInputService.MouseEnabled
end

-- ==================== 选择器自毁系统（防大服务器卡顿） ====================
-- 本脚本本质是"脚本选择器"：玩家选定游戏、对应游戏脚本开始执行后，
-- 选择器积累的 GUI / 常驻全局连接 / 大表缓存若继续留在内存里空转，
-- 大型服务器中会越玩越卡。ExecuteGame 成功编译游戏脚本后会调用
-- PurgeSelector() 把整个选择器一键自毁。
-- 注意：外层 BS 防抓包保护壳（IntegrityCheck 循环、hookfunction 检测循环、
-- CoreGui 监控）不属于选择器，一律不触碰，选完游戏后保护照常运行。
local SelectorConnections = {}   -- 选择器创建的长生命周期全局连接（仅拖拽监听等）
local SelectorPurged = false     -- 自毁防重入标记

local function cleanupAllGuis()
    for _, gui in pairs(playerGui:GetChildren()) do
        if gui.Name == "WXHUBLoader" or gui.Name == "WXHUBGameList" then
            gui:Destroy()
        end
    end
end

local function createParticle(parent)
    local particle = Instance.new("Frame")
    particle.Size = UDim2.new(0, math.random(2, 4), 0, math.random(2, 4))
    particle.Position = UDim2.new(math.random(0, 100)/100, 0, math.random(0, 100)/100, 0)
    particle.BackgroundColor3 = Color3.fromRGB(124, 58, 237)
    particle.BackgroundTransparency = math.random(30, 70)/100
    particle.BorderSizePixel = 0
    particle.ZIndex = 6
    particle.Parent = parent
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0.5, 0)
    corner.Parent = particle
    spawn(function()
        while particle.Parent do
            local moveInfo = TweenInfo.new(math.random(20, 40)/10, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
            local newPos = UDim2.new(math.random(0, 100)/100, 0, math.random(0, 100)/100, 0)
            local moveTween = TweenService:Create(particle, moveInfo, {Position = newPos})
            moveTween:Play()
            wait(math.random(20, 40)/10)
        end
    end)
end

local function showLoadingAnimation(onComplete)
    cleanupAllGuis()

    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "WXHUBLoader"
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    screenGui.ResetOnSpawn = false
    screenGui.IgnoreGuiInset = true
    screenGui.Parent = playerGui

    local background = Instance.new("Frame")
    background.Size = UDim2.new(1, 0, 1, 0)
    background.Position = UDim2.new(0, 0, 0, 0)
    background.BackgroundColor3 = Color3.fromRGB(12, 8, 22)
    background.BackgroundTransparency = 0.3
    background.BorderSizePixel = 0
    background.ZIndex = 1
    background.Parent = screenGui

    local backgroundGradient = Instance.new("UIGradient")
    backgroundGradient.Color = ColorSequence.new{
        ColorSequenceKeypoint.new(0, Color3.fromRGB(20, 12, 36)),
        ColorSequenceKeypoint.new(0.3, Color3.fromRGB(16, 11, 32)),
        ColorSequenceKeypoint.new(0.7, Color3.fromRGB(12, 8, 22)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(19, 12, 36))
    }
    backgroundGradient.Rotation = 45
    backgroundGradient.Parent = background

    spawn(function()
        while background.Parent do
            local rotateInfo = TweenInfo.new(12, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, 0, true)
            local rotateTween = TweenService:Create(backgroundGradient, rotateInfo, {Rotation = 135})
            rotateTween:Play()
            wait(12)
        end
    end)

    local viewportSize = workspace.CurrentCamera.ViewportSize
    local isMobile = IsMobile()
    local minWidth = 280
    local maxWidth = isMobile and 400 or 600
    local baseWidth = math.max(minWidth, math.min(viewportSize.X * (isMobile and 0.9 or 0.4), maxWidth))
    local baseHeight = math.max(200, baseWidth * 0.618)
    
    local mainContainer = Instance.new("Frame")
    mainContainer.Size = UDim2.new(0, baseWidth, 0, baseHeight)
    mainContainer.Position = UDim2.new(0, -baseWidth - 100, 0.5, -baseHeight/2)
    mainContainer.BackgroundColor3 = Color3.fromRGB(26, 16, 46)
    mainContainer.BackgroundTransparency = 0.05
    mainContainer.BorderSizePixel = 0
    mainContainer.ZIndex = 3
    mainContainer.Parent = screenGui

    local mainCorner = Instance.new("UICorner")
    mainCorner.CornerRadius = UDim.new(0, 28)
    mainCorner.Parent = mainContainer

    local shadowStroke1 = Instance.new("UIStroke")
    shadowStroke1.Thickness = 0.5
    shadowStroke1.Color = Color3.fromRGB(12, 8, 22)
    shadowStroke1.Transparency = 0.7
    shadowStroke1.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    shadowStroke1.Parent = mainContainer

    local mainStroke = Instance.new("UIStroke")
    mainStroke.Thickness = 0.5
    mainStroke.Color = Color3.fromRGB(124, 58, 237)
    mainStroke.Transparency = 0
    mainStroke.Parent = mainContainer

    local gradient = Instance.new("UIGradient")
    gradient.Color = ColorSequence.new{
        ColorSequenceKeypoint.new(0, Color3.fromRGB(37, 22, 60)),
        ColorSequenceKeypoint.new(0.2, Color3.fromRGB(29, 18, 50)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(26, 16, 46)),
        ColorSequenceKeypoint.new(0.8, Color3.fromRGB(31, 19, 53)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(34, 21, 56))
    }
    gradient.Rotation = 135
    gradient.Parent = mainContainer

    spawn(function()
