        Icon = "wrench",
        Callback = function() teleportTo(Vector3.new(-227.00, 45.20, -1011.76)) end
    })
    ChapterTab:Space()
    ChapterTab:Button({
        Title = "调查事件的门（要先触发才能坐电梯）",
        Color = makeRainbowColor(150),
        Icon = "door-open",
        Callback = function() teleportTo(Vector3.new(-223.60, 45.33, -887.03)) end
    })
    ChapterTab:Space()

    -- ★ 传送到电梯（彻底去除白色，仅保留彩虹边框与光晕）★
    local elevatorBtn = ChapterTab:Button({
        Title = "传送到电梯",
        Color = Color3.fromRGB(255, 255, 255),
        Icon = "arrow-up-circle",
        Callback = function() teleportTo(Vector3.new(-219.55, 45.41, -870.01)) end
    })

    task.spawn(function()
        local btn = elevatorBtn.Button
        if not btn then return end

        for _, child in pairs(btn:GetChildren()) do
