                    if scaleRem > 0 then
                        scaleBtnM.Text = "冷却" .. scaleRem .. "s"
                    end
                end
                scaleCooling = false
                scaleBtnM.Text = "体型"
            end)
        end)
        scaleBox.FocusLost:Connect(function(enter)
            if enter then
                local num = tonumber(scaleBox.Text)
                if num and not scaleCooling then
                    num = math.floor(num)
                    if num >= 10 and num <= 100 and scaleSetEvent then
                        pcall(function()
                            scaleSetEvent:FireServer({ Settings = { vrscale = num / 10 } })
                        end)
                        scalePanel.Visible = false
                        scaleCooling = true
                        scaleRem = 15
                        scaleBtnM.Text = "冷却" .. scaleRem .. "s"
                        task.spawn(function()
                            while scaleRem > 0 do
                                task.wait(1)
                                scaleRem = scaleRem - 1
                                if scaleRem > 0 then
                                    scaleBtnM.Text = "冷却" .. scaleRem .. "s"
                                end
                            end
                            scaleCooling = false
                            scaleBtnM.Text = "体型"
                        end)
                    end
                end
            end
        end)

