            local hd = currentHand()
            dirTargetX = hd.x; dirTargetY = hd.y
            dirSliderX = hd.x; dirSliderY = hd.y
            sliderXKnob.Position = UDim2.new((hd.x * 0.5) + 0.5, 0, 0.5, 0)
            sliderYKnob.Position = UDim2.new((hd.y * 0.5) + 0.5, 0, 0.5, 0)
            dirLockBtn.Text = hd.locked and "已锁" or "锁定"
        end

