        local function bindHold(btn, key)
            local pressed = false
            btn.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    pressed = true; keys[key] = true
                    btn.BackgroundTransparency = 0.4
                end
            end)
            btn.InputChanged:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch and pressed then
                    local ap = btn.AbsolutePosition
                    local as = btn.AbsoluteSize
                    local ok = i.Position.X >= ap.X - 20 and i.Position.X <= ap.X + as.X + 20
                           and i.Position.Y >= ap.Y - 20 and i.Position.Y <= ap.Y + as.Y + 20
                    keys[key] = ok
                end
            end)
            btn.InputEnded:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    pressed = false; keys[key] = false
                    btn.BackgroundTransparency = 0.72
                end
            end)
        end
