                    local as = obj.AbsoluteSize
                    if pos.X >= ap.X and pos.X <= ap.X + as.X
                       and pos.Y >= ap.Y and pos.Y <= ap.Y + as.Y then
                        return true
                    end
                end
            end
            return false
        end

        local touchLook = false
        local lastTouch = Vector2.zero
        local JUMP_THRESHOLD = 150

