		end
		HumanoidRootPart.Anchored = val
		task.spawn(function()
			while Toggles.Killall.Value do
				task.wait()
				for _, player in pairs(Players:GetPlayers()) do
					if not Toggles.Killall.Value then break end
					if player == LocalPlayer then continue end
