local function saveConfig()
	local data = {}
	for name, e in pairs(ConfigElements) do
		local ok, val = pcall(e.get)
		if ok and val ~= nil then
			data[name] = val
		end
	end

	local ok, err = pcall(function()
		if isfolder and not isfolder(CONFIG_FOLDER) then
			makefolder(CONFIG_FOLDER)
		end
		writefile(CONFIG_PATH, HttpService:JSONEncode(data))
	end)

	if ok then
		doNotify("配置已保存", 2)
	else
		doNotify("保存失败: " .. tostring(err), 3)
	end
end

local function loadConfig(silent)
	if not (isfile and isfile(CONFIG_PATH)) then
		if not silent then
			doNotify("没有找到配置文件，先点保存", 2)
		end
		return false
	end

	local ok, data = pcall(function()
		return HttpService:JSONDecode(readfile(CONFIG_PATH))
	end)

	if not ok or type(data) ~= "table" then
		if not silent then
			doNotify("配置文件损坏", 2)
		end
		return false
	end

	for name, val in pairs(data) do
		local e = ConfigElements[name]
		if e then
			pcall(function()
				e.set(val)
			end)
		end
	end

	if not silent then
		doNotify("配置已加载", 2)
	end
	return true
end

local function clearConfig()
	local ok = pcall(function()
		if delfile and isfile and isfile(CONFIG_PATH) then
			delfile(CONFIG_PATH)
		end
	end)
	if ok then
		doNotify("配置已删除", 2)
	else
		doNotify("删除失败", 2)
	end
end

