local translatedTexts = {}
local translating = {}

local function isEnglish(text)
    if not text or text == "" then return false end
    local letters = 0
    local total = 0
    for i = 1, #text do
        local c = text:sub(i, i)
        if c:match("%a") then
            letters = letters + 1
        end
        if c:match("%S") then
            total = total + 1
        end
    end
    if total == 0 then return false end
    return (letters / total) > 0.5
end

local function translateName(name)
    if translatedTexts[name] then
        return translatedTexts[name]
    end
    if translating[name] then
        return name
    end
    if not isEnglish(name) then
        translatedTexts[name] = name
        return name
    end
    translating[name] = true
    task.spawn(function()
        local success, result = pcall(function()
            local encoded = HttpService:UrlEncode(name)
            local url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=zh-CN&dt=t&q=" .. encoded
            local response = game:HttpGet(url)
            local decoded = HttpService:JSONDecode(response)
            if decoded and decoded[1] and decoded[1][1] and decoded[1][1][1] then
                return decoded[1][1][1]
            end
            return name
        end)
        if success and result and result ~= "" then
            translatedTexts[name] = result
        else
            translatedTexts[name] = name
        end
        translating[name] = nil
    end)
    return name
end

local espEnabled = false
local espMonsters = {}
local espConnections = {}

local function getMonsters()
    local monsters = {}
    local entitiesFolder = Workspace:FindFirstChild("Entities")
    if entitiesFolder then
        for _, obj in ipairs(entitiesFolder:GetChildren()) do
            if obj:IsA("Model") and obj:FindFirstChild("Humanoid") and obj:FindFirstChild("HumanoidRootPart") then
                if obj ~= character then
                    table.insert(monsters, obj)
                end
            end
        end
    end
    return monsters
end

local function createEsp(monster)
    if espMonsters[monster] then return end
    local hrp = monster:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "MonsterESP"
    billboard.AlwaysOnTop = true
    billboard.Size = UDim2.new(0, 260, 0, 80)
    billboard.StudsOffset = Vector3.new(0, 5, 0)
    billboard.Adornee = hrp
    billboard.Parent = hrp

    local bg = Instance.new("Frame")
    bg.Name = "BG"
    bg.Size = UDim2.new(1, 0, 1, 0)
    bg.BackgroundColor3 = Color3.fromRGB(180, 0, 0)
    bg.BackgroundTransparency = 0.15
    bg.BorderSizePixel = 0
    bg.Parent = billboard

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(255, 80, 80)
    stroke.Thickness = 3
    stroke.Parent = bg

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = bg

    local nameLabel = Instance.new("TextLabel")
    nameLabel.Name = "NameLabel"
    nameLabel.Size = UDim2.new(1, -10, 0.5, 0)
    nameLabel.Position = UDim2.new(0, 5, 0.05, 0)
    nameLabel.BackgroundTransparency = 1
    nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    nameLabel.TextStrokeTransparency = 0.1
    nameLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    nameLabel.Font = Enum.Font.GothamBold
    nameLabel.TextSize = 16
    nameLabel.Text = translateName(monster.Name)
    nameLabel.Parent = bg

    local distLabel = Instance.new("TextLabel")
    distLabel.Name = "DistLabel"
    distLabel.Size = UDim2.new(1, -10, 0.4, 0)
    distLabel.Position = UDim2.new(0, 5, 0.55, 0)
    distLabel.BackgroundTransparency = 1
    distLabel.TextColor3 = Color3.fromRGB(255, 220, 220)
    distLabel.TextStrokeTransparency = 0.1
    distLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    distLabel.Font = Enum.Font.GothamBold
    distLabel.TextSize = 14
    distLabel.Text = "距离: 计算中..."
    distLabel.Parent = bg

    local box = Instance.new("BoxHandleAdornment")
    box.Name = "ESPBox"
    box.AlwaysOnTop = true
    box.ZIndex = 10
    box.Adornee = hrp
    box.Size = Vector3.new(5, 7, 5)
    box.Color3 = Color3.fromRGB(255, 0, 0)
    box.Transparency = 0.7
    box.Parent = hrp

    espMonsters[monster] = {billboard = billboard, box = box, nameLabel = nameLabel, distLabel = distLabel}

    local conn
    conn = RunService.RenderStepped:Connect(function()
        if not espEnabled or not monster.Parent then
            if billboard then billboard:Destroy() end
            if box then box:Destroy() end
            espMonsters[monster] = nil
            if conn then conn:Disconnect() end
            return
        end
        if hrp and humanoidRootPart then
            local dist = (hrp.Position - humanoidRootPart.Position).Magnitude
            distLabel.Text = "距离: " .. math.floor(dist) .. "m"
            local translated = translatedTexts[monster.Name]
            if translated then
                nameLabel.Text = translated
            else
                nameLabel.Text = monster.Name
            end
        end
    end)
    table.insert(espConnections, conn)
end

local function updateEsp()
    if not espEnabled then
        for monster, data in pairs(espMonsters) do
            if data.billboard then data.billboard:Destroy() end
            if data.box then data.box:Destroy() end
        end
        espMonsters = {}
        for _, conn in ipairs(espConnections) do
            conn:Disconnect()
        end
        espConnections = {}
        return
    end
    local monsters = getMonsters()
    for _, monster in ipairs(monsters) do
        createEsp(monster)
    end
end

local entityAddedConn
local function startEsp()
    if entityAddedConn then entityAddedConn:Disconnect() end
    local entitiesFolder = Workspace:FindFirstChild("Entities")
    if not entitiesFolder then return end
    entityAddedConn = entitiesFolder.ChildAdded:Connect(function(child)
        if espEnabled and child:IsA("Model") and child:FindFirstChild("Humanoid") and child:FindFirstChild("HumanoidRootPart") then
            task.wait(0.5)
            createEsp(child)
        end
    end)
end

