            if obj:IsA("Atmosphere") then
                obj:SetAttribute("_orig_density", obj.Density)
                obj:SetAttribute("_orig_haze", obj.Haze)
                obj:SetAttribute("_orig_glare", obj.Glare)
                obj.Density = 0
                obj.Haze = 0
                obj.Glare = 0
            end
        end
        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj.Name:lower():find("fog") and (obj:IsA("BasePart") or obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA("Fire")) then
                obj:SetAttribute("_orig_enabled", obj.Enabled)
                obj.Enabled = false
            end
        end
    else
        local fs = Lighting:GetAttribute("_orig_fog_start")
        local fe = Lighting:GetAttribute("_orig_fog_end")
        local fc = Lighting:GetAttribute("_orig_fog_color")
        if fs ~= nil then Lighting.FogStart = fs end
        if fe ~= nil then Lighting.FogEnd = fe end
        if fc ~= nil then Lighting.FogColor = fc end
        for _, obj in ipairs(Lighting:GetChildren()) do
            if obj:IsA("Atmosphere") then
                local d = obj:GetAttribute("_orig_density")
                local h = obj:GetAttribute("_orig_haze")
                local g = obj:GetAttribute("_orig_glare")
                if d ~= nil then obj.Density = d end
                if h ~= nil then obj.Haze = h end
                if g ~= nil then obj.Glare = g end
            end
        end
        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj.Name:lower():find("fog") and (obj:IsA("BasePart") or obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA("Fire")) then
                local e = obj:GetAttribute("_orig_enabled")
                if e ~= nil then obj.Enabled = e end
            end
        end
    end
end)

