-- ==================== 黑曜石API → WindUI 适配层（功能逻辑零改动） ====================
local Library = {}
Library.Options = {}
Library.Toggles = {}
Library.Unloaded = false

function Library:Notify(msg, dur)
    if type(msg) == "table" then
        pcall(function() WindUI:Notify({
            Title = msg.Title or "提示",
            Content = msg.Description or msg.Content or "",
            Icon = "bell",
            Duration = msg.Time or msg.Duration or dur or 3,
        }) end)
    else
        pcall(function() WindUI:Notify({
            Title = "提示", Content = tostring(msg), Icon = "bell",
            Duration = dur or 3,
        }) end)
    end
end

function Library:Unload()
    Library.Unloaded = true
    pcall(function() Window:Close(true) end)
    pcall(function() Window:Destroy() end)
end

local FakeWindow = {}
local GroupboxMT = {}; GroupboxMT.__index = GroupboxMT
local TabMT = {}; TabMT.__index = TabMT

function TabMT:AddLeftGroupbox(title)
    return setmetatable({ _t = self._t }, GroupboxMT)
end
TabMT.AddRightGroupbox = TabMT.AddLeftGroupbox

function FakeWindow:AddTab(name, icon)
    local okS, section = pcall(function() return Window:Section({ Title = name, Icon = icon, Opened = true }) end)
    if not okS then section = nil end
    local okT, tab
    if section then
        okT, tab = pcall(function() return section:Tab({ Title = name, Icon = icon or "info", IconThemed = true }) end)
    end
    if not okT or not tab then
        tab = setmetatable({
            Toggle=function() return {} end, Button=function() end, Slider=function() end,
            Dropdown=function() return {} end, Input=function() return {} end,
            Paragraph=function() end, Space=function() end, ColorPicker=function() return {} end,
            Section=function() end,
        }, {__index=function() return function() end end})
    end
    return setmetatable({ _t = tab }, TabMT)
end

function GroupboxMT:AddToggle(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default and true or false }
    local ok, w = pcall(function()
        return self._t:Toggle({
            Title = opts.Text or opts.Title or tostring(flag),
            Desc = opts.Tooltip,
            Value = proxy.Value,
            Callback = function(v)
                proxy.Value = v and true or false
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    proxy._ok = ok; proxy._w = w
    function proxy.SetValue(_, v)
        proxy.Value = v and true or false
        if ok and w then pcall(function() w:Set(v) end) end
    end
    function proxy.AddColorPicker(_, cflag, copts)
        return GroupboxMT.AddColorPicker(self, cflag, copts)
    end
    Library.Toggles[flag] = proxy
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddButton(a, b)
    local text, fn
    if type(a) == "table" then
        text = a.Text or a.Title; fn = a.Func or a.Callback
    else
        text = a; fn = b
    end
    pcall(function()
        self._t:Button({ Title = tostring(text), Callback = function()
            if fn then pcall(fn) end
        end })
    end)
end

function GroupboxMT:AddSlider(flag, opts)
    opts = opts or {}
    local title = opts.Text or opts.Title or tostring(flag)
    local vmin = opts.Min or (opts.Value and opts.Value.Min) or 0
    local vmax = opts.Max or (opts.Value and opts.Value.Max) or 100
    local vdef = opts.Default or (opts.Value and opts.Value.Default) or vmin
    pcall(function()
        self._t:Slider({
            Title = title,
            Value = { Min = vmin, Max = vmax, Default = vdef },
            Callback = function(v)
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
end

function GroupboxMT:AddDropdown(flag, opts)
    opts = opts or {}
    local vals = opts.Values or opts.Options or {}
    local def = opts.Default
    if type(def) == "number" and vals[def] ~= nil then def = vals[def] end
    local proxy = { Value = def, _items = vals }
    local ok, w = pcall(function()
        return self._t:Dropdown({
            Title = opts.Text or opts.Title or tostring(flag),
            Values = vals, Default = def, Multi = opts.Multi,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    proxy._ok = ok; proxy._w = w
    function proxy.Clear(_)
        proxy._items = {}
        if ok and w then
            pcall(function() w:Refresh({}, true) end)
            pcall(function() w:Clear() end)
        end
    end
    function proxy.Add(_, v)
        table.insert(proxy._items, v)
        if ok and w then
            pcall(function() w:Add(v) end)
            pcall(function() w:Refresh(proxy._items, true) end)
        end
    end
    function proxy.SetOptions(_, list)
        proxy._items = list
        if ok and w then
            pcall(function() w:Refresh(list, true) end)
            pcall(function() w:SetOptions(list) end)
        end
    end
    Library.Options[flag] = proxy
    Library.Toggles[flag] = proxy
    return proxy
end

function GroupboxMT:AddInput(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default or "" }
    pcall(function()
        self._t:Input({
            Title = opts.Text or opts.Title or tostring(flag),
            Default = opts.Default, Placeholder = opts.Placeholder,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddLabel(text)
    pcall(function() self._t:Paragraph({ Title = tostring(text) }) end)
    local lbl = {}
    function lbl.AddKeyPicker(_, kflag, kopts)
        local picker = { Value = kopts and kopts.Default or nil }
        function picker.SetValue(_, v) picker.Value = v end
        Library.Options[kflag] = picker
        return picker
    end
    function lbl.AddColorPicker(_, cflag, copts)
        GroupboxMT.AddColorPicker(self, cflag, copts)
        return lbl
    end
    return lbl
end

function GroupboxMT:AddDivider() pcall(function() self._t:Space({ Columns = 1 }) end) end
function GroupboxMT:AddSpace() pcall(function() self._t:Space({ Columns = 1 }) end) end

function GroupboxMT:AddColorPicker(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default }
    pcall(function()
        self._t:ColorPicker({
            Title = opts.Title or opts.Text or tostring(flag),
            Default = opts.Default,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddCode(opts)
    opts = opts or {}
    pcall(function() self._t:Paragraph({ Title = tostring(opts.Text or opts.Title or "") }) end)
end
function GroupboxMT:AddImage(opts)
    opts = opts or {}
    pcall(function() self._t:Paragraph({ Title = tostring(opts.Name or opts.Title or "") }) end)
end
function GroupboxMT:AddKeyPicker(flag, opts)
    local p = { Value = opts and opts.Default or nil }
    function p.SetValue(_, v) p.Value = v end
    Library.Options[flag] = p
    return p
end

local Options = Library.Options
local Toggles = Library.Toggles

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local player = Players.LocalPlayer

local isMoneyRunning = false
local isPunchRunning = false
local punchSpeed = 0.5
local noClipEnabled = false
local noclipConnection = nil

local espEnabled = false
local espBillboards = {}
local espConnections = {}

local flySpeed = 50
local flyActive = false
local flyConn = nil
local bodyVelocity = nil
local Camera = workspace.CurrentCamera

local BUY_COORDS = Vector3.new(6819.8, 17.5, 28.9)
local SELL_COORDS = Vector3.new(211.2, 17.4, -43.3)
local LAUNDER_COORDS = Vector3.new(6808.8, 17.6, -34.9)

local function getHRP()
    local char = player.Character
    if not char then return nil end
    return char:FindFirstChild("HumanoidRootPart")
end

local function teleportTo(position)
    local hrp = getHRP()
    if hrp then
        hrp.CFrame = CFrame.new(position)
    end
end

local function buyAvacados()
    local item = workspace.WorldBuyableItems:FindFirstChild("Crate Of Avacados")
    if item then
        local args = {[1] = item}
        ReplicatedStorage.__remotes.WorldBuyableItemService.PurchaseWorldBuyableItem:FireServer(unpack(args))
    end
end

local function sellAvacados()
    local sellArgs = {[1] = workspace.NPC.Seller4}
    ReplicatedStorage.__remotes.SmuggleService.SellSmuggledGoods:FireServer(unpack(sellArgs))
end

local function setBackpackOrder()
    local orderArgs = {
        [1] = {
            [1] = "name:Fists",
            [2] = "name:Passport",
            [3] = "name:Briefcase"
        }
    }
    ReplicatedStorage.__remotes.BackpackService.SetBackpackToolOrder:FireServer(unpack(orderArgs))
end

local function launderMoney()
    local trigger = workspace.LaunderPrompts:FindFirstChild("LaunderTrigger")
    if trigger then
        local part = trigger:FindFirstChild("PromptPart")
        if part then
            local args = {[1] = part}
            ReplicatedStorage.__remotes.SmuggleService.LaunderBriefcase:FireServer(unpack(args))
        end
    end
end

local function punch()
    ReplicatedStorage.__remotes.Fists.Punch:InvokeServer()
end

local function setNoclip(state)
    noClipEnabled = state
    if noclipConnection then
        noclipConnection:Disconnect()
        noclipConnection = nil
    end
    if state then
        noclipConnection = RunService.Stepped:Connect(function()
            local char = player.Character
            if char then
                for _, p in ipairs(char:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.CanCollide = false
                    end
                end
            end
        end)
    else
        local char = player.Character
        if char then
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.CanCollide = true
                end
            end
        end
    end
end

local function flyTo(targetPos)
    local hrp = getHRP()
    if not hrp then return false end

    local startPos = hrp.Position
    local distance = (targetPos - startPos).Magnitude
    local duration = distance / 150
    local startTime = tick()

    while true do
        if not isMoneyRunning then return false end

        local currentHRP = getHRP()
        if not currentHRP then return false end

        local elapsed = tick() - startTime
        if elapsed >= duration then
            currentHRP.CFrame = CFrame.new(targetPos)
            return true
        end

        local alpha = elapsed / duration
        local newPos = startPos:Lerp(targetPos, alpha)
        currentHRP.CFrame = CFrame.new(newPos)

        task.wait(0.03)
    end
end

local function wiggleInPlace(duration)
    local hrp = getHRP()
    if not hrp then return false end
    local basePos = hrp.Position
    local start = tick()
    while tick() - start < duration do
        if not isMoneyRunning then return false end
        local currentHRP = getHRP()
        if not currentHRP then return false end
        local offsetX = math.sin(tick() * 2) * 0.1
        local offsetZ = math.cos(tick() * 2) * 0.1
        currentHRP.CFrame = CFrame.new(basePos.X + offsetX, basePos.Y, basePos.Z + offsetZ)
        task.wait(0.1)
    end
    return true
end

local function waitSeconds(seconds)
    local start = tick()
    while tick() - start < seconds do
        task.wait(0.1)
        if not isMoneyRunning then return false end
    end
    return true
end

local function doOneCycle()
    setNoclip(true)

    if not flyTo(BUY_COORDS) then return false end
    wiggleInPlace(3)
    buyAvacados()
    buyAvacados()
    buyAvacados()
    if not waitSeconds(5) then return false end

    setBackpackOrder()
    task.wait(1)

    if not flyTo(SELL_COORDS) then return false end
    wiggleInPlace(3)
    sellAvacados()
    task.wait(1)
    sellAvacados()
    task.wait(1)
    sellAvacados()
    if not waitSeconds(5) then return false end

    if not flyTo(LAUNDER_COORDS) then return false end
    wiggleInPlace(3)
    launderMoney()
    task.wait(1)
    launderMoney()
    task.wait(1)
    launderMoney()
    if not waitSeconds(5) then return false end

    setNoclip(false)
    return true
end

local function moneyLoop()
    while isMoneyRunning do
        local success = doOneCycle()
        if not success then break end
        if not waitSeconds(3) then break end
    end
    setNoclip(false)
end

local function punchLoop()
    while isPunchRunning do
        punch()
        task.wait(punchSpeed)
    end
end

local function startFly()
    local hrp = getHRP()
    if not hrp then return end
    bodyVelocity = Instance.new("BodyVelocity")
    bodyVelocity.Velocity = Vector3.zero
    bodyVelocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
    bodyVelocity.P = 1250
    bodyVelocity.Parent = hrp
    flyConn = RunService.RenderStepped:Connect(function()
        local camLook = Camera.CFrame.LookVector
        bodyVelocity.Velocity = camLook * flySpeed
    end)
end

local function stopFly()
    if flyConn then flyConn:Disconnect() flyConn = nil end
    if bodyVelocity then bodyVelocity:Destroy() bodyVelocity = nil end
end

local function cleanupESP(targetPlayer)
    if espConnections[targetPlayer] then
        for _, conn in ipairs(espConnections[targetPlayer]) do
            pcall(function() conn:Disconnect() end)
        end
        espConnections[targetPlayer] = nil
    end
    local char = targetPlayer.Character
    if char then
        pcall(function()
            local hl = char:FindFirstChild("EspHighlight")
            if hl then hl:Destroy() end
        end)
        pcall(function()
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                local bb = hrp:FindFirstChild("EspBillboard")
                if bb then bb:Destroy() end
            end
        end)
    end
    espBillboards[targetPlayer] = nil
end

local function createESP(targetPlayer)
    if targetPlayer == player then return end
    local char = targetPlayer.Character
    if not char then return end
    cleanupESP(targetPlayer)
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then
        task.spawn(function()
            local success = pcall(function() char:WaitForChild("HumanoidRootPart", 5) end)
            if success and espEnabled and targetPlayer.Parent then
                createESP(targetPlayer)
            end
        end)
        return
    end
    local highlight = Instance.new("Highlight")
    highlight.Name = "EspHighlight"
    highlight.Parent = char
    highlight.FillTransparency = 0.5
    highlight.FillColor = Color3.fromRGB(255, 255, 0)
    highlight.OutlineColor = Color3.fromRGB(255, 255, 0)
    highlight.OutlineTransparency = 0
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "EspBillboard"
    billboard.Parent = hrp
    billboard.Size = UDim2.new(0, 200, 0, 50)
    billboard.StudsOffset = Vector3.new(0, 3, 0)
    billboard.AlwaysOnTop = true
    local nameLabel = Instance.new("TextLabel")
    nameLabel.Name = "NameLabel"
    nameLabel.Parent = billboard
    nameLabel.Size = UDim2.new(1, 0, 0.5, 0)
    nameLabel.BackgroundTransparency = 1
    nameLabel.Text = targetPlayer.Name
    nameLabel.TextColor3 = Color3.fromRGB(255, 255, 0)
    nameLabel.TextStrokeTransparency = 0
    nameLabel.TextSize = 14
    nameLabel.Font = Enum.Font.SourceSansBold
    local distLabel = Instance.new("TextLabel")
    distLabel.Name = "DistLabel"
    distLabel.Parent = billboard
    distLabel.Size = UDim2.new(1, 0, 0.5, 0)
    distLabel.Position = UDim2.new(0, 0, 0.5, 0)
    distLabel.BackgroundTransparency = 1
    distLabel.Text = "0m"
    distLabel.TextColor3 = Color3.fromRGB(255, 255, 0)
    distLabel.TextStrokeTransparency = 0
    distLabel.TextSize = 12
    distLabel.Font = Enum.Font.SourceSans
    espBillboards[targetPlayer] = billboard
end

local function setupPlayerESP(targetPlayer)
    if targetPlayer == player then return end
    if espConnections[targetPlayer] then
        for _, conn in ipairs(espConnections[targetPlayer]) do
            pcall(function() conn:Disconnect() end)
        end
    end
    espConnections[targetPlayer] = {}
    table.insert(espConnections[targetPlayer], targetPlayer.CharacterAdded:Connect(function(char)
        task.spawn(function()
            pcall(function() char:WaitForChild("HumanoidRootPart", 5) end)
            if espEnabled then
                task.wait(0.1)
                createESP(targetPlayer)
            end
        end)
    end))
    table.insert(espConnections[targetPlayer], targetPlayer.CharacterRemoving:Connect(function()
        cleanupESP(targetPlayer)
    end))
    if targetPlayer.Character and espEnabled then
        createESP(targetPlayer)
    end
end

RunService.RenderStepped:Connect(function()
    if not espEnabled then return end
    local myChar = player.Character
    local myPos = myChar and myChar:FindFirstChild("HumanoidRootPart") and myChar.HumanoidRootPart.Position
    for targetPlayer, billboard in pairs(espBillboards) do
        if targetPlayer.Parent and targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart") and billboard and billboard.Parent then
            local distLabel = billboard:FindFirstChild("DistLabel")
            if distLabel and myPos then
