-- ==================== 黑曜石API → WindUI 适配层（功能逻辑零改动） ====================
local Library = {}
Library.Options = {}
Library.Toggles = {}
Library.Unloaded = false

function Library:Notify(msg, dur)
    if type(msg) == "table" then
        pcall(function() WindUI:Notify({
            Title = msg.Title or "提示",
            Content = msg.Description or msg.Content or "",
            Icon = "bell",
            Duration = msg.Time or msg.Duration or dur or 3,
        }) end)
    else
        pcall(function() WindUI:Notify({
            Title = "提示", Content = tostring(msg), Icon = "bell",
            Duration = dur or 3,
        }) end)
    end
end

function Library:Unload()
    Library.Unloaded = true
    pcall(function() Window:Close(true) end)
    pcall(function() Window:Destroy() end)
end

local FakeWindow = {}
local GroupboxMT = {}; GroupboxMT.__index = GroupboxMT
local TabMT = {}; TabMT.__index = TabMT

function TabMT:AddLeftGroupbox(title)
    return setmetatable({ _t = self._t }, GroupboxMT)
end
TabMT.AddRightGroupbox = TabMT.AddLeftGroupbox

function FakeWindow:AddTab(name, icon)
    local okS, section = pcall(function() return Window:Section({ Title = name, Icon = icon, Opened = true }) end)
    if not okS then section = nil end
    local okT, tab
    if section then
        okT, tab = pcall(function() return section:Tab({ Title = name, Icon = icon or "info", IconThemed = true }) end)
    end
    if not okT or not tab then
        tab = setmetatable({
            Toggle=function() return {} end, Button=function() end, Slider=function() end,
            Dropdown=function() return {} end, Input=function() return {} end,
            Paragraph=function() end, Space=function() end, ColorPicker=function() return {} end,
            Section=function() end,
        }, {__index=function() return function() end end})
    end
    return setmetatable({ _t = tab }, TabMT)
end

function GroupboxMT:AddToggle(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default and true or false }
    local ok, w = pcall(function()
        return self._t:Toggle({
            Title = opts.Text or opts.Title or tostring(flag),
            Desc = opts.Tooltip,
            Value = proxy.Value,
            Callback = function(v)
                proxy.Value = v and true or false
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    proxy._ok = ok; proxy._w = w
    function proxy.SetValue(_, v)
        proxy.Value = v and true or false
        if ok and w then pcall(function() w:Set(v) end) end
    end
    function proxy.AddColorPicker(_, cflag, copts)
        return GroupboxMT.AddColorPicker(self, cflag, copts)
    end
    Library.Toggles[flag] = proxy
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddButton(a, b)
    local text, fn
    if type(a) == "table" then
        text = a.Text or a.Title; fn = a.Func or a.Callback
    else
        text = a; fn = b
    end
    pcall(function()
        self._t:Button({ Title = tostring(text), Callback = function()
            if fn then pcall(fn) end
        end })
    end)
end

function GroupboxMT:AddSlider(flag, opts)
    opts = opts or {}
    local title = opts.Text or opts.Title or tostring(flag)
    local vmin = opts.Min or (opts.Value and opts.Value.Min) or 0
    local vmax = opts.Max or (opts.Value and opts.Value.Max) or 100
    local vdef = opts.Default or (opts.Value and opts.Value.Default) or vmin
    pcall(function()
        self._t:Slider({
            Title = title,
            Value = { Min = vmin, Max = vmax, Default = vdef },
            Callback = function(v)
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
end

function GroupboxMT:AddDropdown(flag, opts)
    opts = opts or {}
    local vals = opts.Values or opts.Options or {}
    local def = opts.Default
    if type(def) == "number" and vals[def] ~= nil then def = vals[def] end
    local proxy = { Value = def, _items = vals }
    local ok, w = pcall(function()
        return self._t:Dropdown({
            Title = opts.Text or opts.Title or tostring(flag),
            Values = vals, Default = def, Multi = opts.Multi,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    proxy._ok = ok; proxy._w = w
    function proxy.Clear(_)
        proxy._items = {}
        if ok and w then
            pcall(function() w:Refresh({}, true) end)
            pcall(function() w:Clear() end)
        end
    end
    function proxy.Add(_, v)
        table.insert(proxy._items, v)
        if ok and w then
            pcall(function() w:Add(v) end)
            pcall(function() w:Refresh(proxy._items, true) end)
        end
    end
    function proxy.SetOptions(_, list)
        proxy._items = list
        if ok and w then
            pcall(function() w:Refresh(list, true) end)
            pcall(function() w:SetOptions(list) end)
        end
    end
    Library.Options[flag] = proxy
    Library.Toggles[flag] = proxy
    return proxy
end

function GroupboxMT:AddInput(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default or "" }
    pcall(function()
        self._t:Input({
            Title = opts.Text or opts.Title or tostring(flag),
            Default = opts.Default, Placeholder = opts.Placeholder,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddLabel(text)
    pcall(function() self._t:Paragraph({ Title = tostring(text) }) end)
    local lbl = {}
    function lbl.AddKeyPicker(_, kflag, kopts)
        local picker = { Value = kopts and kopts.Default or nil }
        function picker.SetValue(_, v) picker.Value = v end
        Library.Options[kflag] = picker
        return picker
    end
    function lbl.AddColorPicker(_, cflag, copts)
        GroupboxMT.AddColorPicker(self, cflag, copts)
        return lbl
    end
    return lbl
end

function GroupboxMT:AddDivider() pcall(function() self._t:Space({ Columns = 1 }) end) end
function GroupboxMT:AddSpace() pcall(function() self._t:Space({ Columns = 1 }) end) end

function GroupboxMT:AddColorPicker(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default }
    pcall(function()
        self._t:ColorPicker({
            Title = opts.Title or opts.Text or tostring(flag),
            Default = opts.Default,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddCode(opts)
    opts = opts or {}
    pcall(function() self._t:Paragraph({ Title = tostring(opts.Text or opts.Title or "") }) end)
end
function GroupboxMT:AddImage(opts)
    opts = opts or {}
    pcall(function() self._t:Paragraph({ Title = tostring(opts.Name or opts.Title or "") }) end)
end
function GroupboxMT:AddKeyPicker(flag, opts)
    local p = { Value = opts and opts.Default or nil }
    function p.SetValue(_, v) p.Value = v end
    Library.Options[flag] = p
    return p
end

