    bottomGlow.Name = "BottomGlow"; bottomGlow.Size = UDim2.new(1, 0, 0.25, 0)
    bottomGlow.Position = UDim2.new(0, 0, 0.75, 0)
    bottomGlow.BackgroundTransparency = 1; bottomGlow.ZIndex = 0; bottomGlow.Parent = mf
    local bg2 = Instance.new("UIGradient")
    bg2.Color = ColorSequence.new(makeRainbowColor(180), makeRainbowColor(0))
    bg2.Transparency = NumberSequence.new(1, 0.92); bg2.Rotation = 90; bg2.Parent = bottomGlow
    task.spawn(function()
        while topGlow and topGlow.Parent do
            task.wait(0.1)
            local c1 = makeRainbowColor(0); local c2 = makeRainbowColor(180)
            tg.Color = ColorSequence.new(c1, c2); bg2.Color = ColorSequence.new(c2, c1)
        end
    end)
end)

task.spawn(function()
