local translateCache = {}

local function getItemName(enName)
    if translateCache[enName] then
        return translateCache[enName]
    end
    local cn = itemTranslations[enName]
    if cn then
        translateCache[enName] = cn
        return cn
    end
    translateCache[enName] = enName
    return enName
end

