local GAMEFOLDERS = Workspace:FindFirstChild("GAMEFOLDERS")
local CustomersFolder = GAMEFOLDERS and GAMEFOLDERS:FindFirstChild("Customers") and GAMEFOLDERS.Customers:FindFirstChild("Alive")
local CustomersDeadFolder = GAMEFOLDERS and GAMEFOLDERS:FindFirstChild("Customers") and (GAMEFOLDERS.Customers:FindFirstChild("Dead") or GAMEFOLDERS.Customers:FindFirstChild("DeadCustomers"))
local NPCsFolder = GAMEFOLDERS and GAMEFOLDERS:FindFirstChild("NPCs")

local NPCTags = {
    Customer = {},
    Enemy = {},
}

local COPS = CONFIG.EnemyCategories.Cop
local RATS = CONFIG.EnemyCategories.Rat
local COP_KEYWORDS = { "COP", "POLICE", "OFFICER", "SWAT", "RIOT", "SNIPER", "UNDERCOVER" }
local RAT_KEYWORDS = { "RAT" }

local function NameMatchesKeywords(name, keywords)
    if not name then return false end
    local upName = string.upper(name)
    for _, kw in ipairs(keywords) do
        if string.find(upName, kw, 1, true) then
            return true
        end
    end
    return false
end

local function IsEnemyCategory(model)
    if not model or not model:IsA("Model") then return false end
    if not model:FindFirstChild("Humanoid") then return false end
    local name = model.Name
    if COPS[name] == true or RATS[name] == true then return true end
    if NameMatchesKeywords(name, COP_KEYWORDS) then return true end
    if NameMatchesKeywords(name, RAT_KEYWORDS) then return true end
    return false
end

local function IsCop(model)
    if not model or not model:IsA("Model") then return false end
    local name = model.Name
    if COPS[name] == true then return true end
    return NameMatchesKeywords(name, COP_KEYWORDS)
end

local function IsRat(model)
    if not model or not model:IsA("Model") then return false end
    local name = model.Name
    if RATS[name] == true then return true end
    return NameMatchesKeywords(name, RAT_KEYWORDS)
end

local function ClassifyNPC(model)
    if not model or not model:IsA("Model") then return nil end
    if not model:FindFirstChild("Humanoid") then return nil end
    if CustomersFolder and model.Parent == CustomersFolder then
        return "customer"
    end
    if IsCop(model) then return "cop" end
    if IsRat(model) then return "rat" end
    if NPCsFolder and model:IsDescendantOf(NPCsFolder) then
        return "enemy"
    end
    return nil
end

local ESP_Enabled = false

local function AddEnemy(model)
    if not model or not model.Parent then return end
    for _, e in ipairs(NPCTags.Enemy) do
        if e == model then return end
    end
    table.insert(NPCTags.Enemy, model)
end

local function ScanAll()
    table.clear(NPCTags.Customer)
    table.clear(NPCTags.Enemy)
    if CustomersFolder then
        for _, model in ipairs(CustomersFolder:GetChildren()) do
            if model:IsA("Model") and model:FindFirstChild("Humanoid") then
                table.insert(NPCTags.Customer, model)
            end
        end
    end
    if NPCsFolder then
        for _, model in ipairs(NPCsFolder:GetChildren()) do
            if model:IsA("Model") and model.Name ~= "Dead" and model:FindFirstChild("Humanoid") then
                AddEnemy(model)
            end
        end
    end
    for _, model in ipairs(Workspace:GetDescendants()) do
        if IsEnemyCategory(model) then
            AddEnemy(model)
        end
    end
end

ScanAll()

