                        if myPos then
                            local dist = (thrp.Position - myPos).Magnitude
                            bb.DistLabel.Text = s.format("%.1f m", dist)
                        else
                            bb.DistLabel.Text = "??? m"
                        end
                    else
                        if espLabels[p] then
                            pcall(function() espLabels[p]:Destroy() end)
                            espLabels[p] = nil
                        end
                    end
                end
            end
        else
            for p, gui in pairs(espLabels) do
                if gui then
                    pcall(function() gui:Destroy() end)
                end
                espLabels[p] = nil
            end
        end
        tsk.wait(0.1)
    end
end)

