            end, "武器箱")
        end)
    end
    group:AddDropdown("Category" .. idx, {
        Values = displayList,
        Default = 1,
        Multi = true,
        Text = "选择要拉取的物资",
    })
    group:AddButton("拉取选中物资", function()
        local selected = Options["Category" .. idx].Value
        local patterns = {}
