	        UrlBox.Position = UDim2.new(0, 10, 0, 0); UrlBox.Size = UDim2.new(1, -20, 1, 0); UrlBox.Font = Enum.Font.Gotham
	        UrlBox.PlaceholderText = "https://example.com/image.png"; UrlBox.Text = ""; UrlBox.TextColor3 = THEME.TextPrimary
