local itemCreators = {
    ["freeze gun"] = createFreezeGun,
    ["vip coil"] = createVipCoil,
    ["radio"] = createRadio,
    ["rainbow flashlight"] = createRainbowFlashlight,
    ["Jetpack"] = createJetpack,
    ["Insanity Coil"] = createInsanityCoil,
    ["Guest's Grimoire"] = createGuestsGrimoire,
    ["Second Chance"] = createSecondChance,
    ["God Mode"] = createGodMode,
}

local function getItem(itemName)
    local stolen = stealTool(itemName)
    if stolen then
        local clone = stolen:Clone()
        clone.Parent = player.Backpack
        return
    end
    local copied = copyTool(itemName)
    if copied then
        local clone = copied:Clone()
        clone.Parent = player.Backpack
        return
    end
    local creator = itemCreators[itemName]
    if creator then
        local tool = creator()
        tool.Parent = player.Backpack
        return
    end
    local basic = Instance.new("Tool")
    basic.Name = itemName
    basic.RequiresHandle = true
    local handle = Instance.new("Part")
    handle.Name = "Handle"
    handle.Size = Vector3.new(1, 1, 1)
    handle.CanCollide = false
    handle.Parent = basic
    basic.Parent = player.Backpack
end

local function buyItem(itemName)
    local hrp = getHRP()
    if not hrp then return end
    local shop = Workspace:FindFirstChild("shopTouchPrompts")
    if shop then
        for _, item in ipairs(shop:GetChildren()) do
            if item:IsA("BasePart") and item.Name == itemName and item:FindFirstChild("TouchInterest") then
                pcall(function()
                    firetouchinterest(hrp, item, 0)
                    firetouchinterest(hrp, item, 1)
                end)
                return
            end
        end
    end
    local vipGivers = Workspace:FindFirstChild("VIP Givers")
    if vipGivers then
        for _, item in ipairs(vipGivers:GetChildren()) do
            if item.Name == itemName and item:FindFirstChild("TouchInterest") then
                pcall(function()
                    firetouchinterest(hrp, item, 0)
                    firetouchinterest(hrp, item, 1)
                end)
                return
            end
        end
    end
end

