-- ==================== 黑曜石API → WindUI 适配层（功能逻辑零改动） ====================
local Library = {}
Library.Options = {}
Library.Toggles = {}
Library.Unloaded = false

function Library:Notify(msg, dur)
    if type(msg) == "table" then
        pcall(function() WindUI:Notify({
            Title = msg.Title or "提示",
            Content = msg.Description or msg.Content or "",
            Icon = "bell",
            Duration = msg.Time or msg.Duration or dur or 3,
        }) end)
    else
        pcall(function() WindUI:Notify({
            Title = "提示", Content = tostring(msg), Icon = "bell",
            Duration = dur or 3,
        }) end)
    end
end

function Library:Unload()
    Library.Unloaded = true
    pcall(function() Window:Close(true) end)
    pcall(function() Window:Destroy() end)
end

local FakeWindow = {}
local GroupboxMT = {}; GroupboxMT.__index = GroupboxMT
local TabMT = {}; TabMT.__index = TabMT

function TabMT:AddLeftGroupbox(title)
    return setmetatable({ _t = self._t }, GroupboxMT)
end
TabMT.AddRightGroupbox = TabMT.AddLeftGroupbox

function FakeWindow:AddTab(name, icon)
    local okS, section = pcall(function() return Window:Section({ Title = name, Icon = icon, Opened = true }) end)
    if not okS then section = nil end
    local okT, tab
    if section then
        okT, tab = pcall(function() return section:Tab({ Title = name, Icon = icon or "info", IconThemed = true }) end)
    end
    if not okT or not tab then
        tab = setmetatable({
            Toggle=function() return {} end, Button=function() end, Slider=function() end,
            Dropdown=function() return {} end, Input=function() return {} end,
            Paragraph=function() end, Space=function() end, ColorPicker=function() return {} end,
            Section=function() end,
        }, {__index=function() return function() end end})
    end
    return setmetatable({ _t = tab }, TabMT)
end

function GroupboxMT:AddToggle(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default and true or false }
    local ok, w = pcall(function()
        return self._t:Toggle({
            Title = opts.Text or opts.Title or tostring(flag),
            Desc = opts.Tooltip,
            Value = proxy.Value,
            Callback = function(v)
                proxy.Value = v and true or false
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    proxy._ok = ok; proxy._w = w
    function proxy.SetValue(_, v)
        proxy.Value = v and true or false
        if ok and w then pcall(function() w:Set(v) end) end
    end
    function proxy.AddColorPicker(_, cflag, copts)
        return GroupboxMT.AddColorPicker(self, cflag, copts)
    end
    Library.Toggles[flag] = proxy
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddButton(a, b)
    local text, fn
    if type(a) == "table" then
        text = a.Text or a.Title; fn = a.Func or a.Callback
    else
        text = a; fn = b
    end
    pcall(function()
        self._t:Button({ Title = tostring(text), Callback = function()
            if fn then pcall(fn) end
        end })
    end)
end

function GroupboxMT:AddSlider(flag, opts)
    opts = opts or {}
    local title = opts.Text or opts.Title or tostring(flag)
    local vmin = opts.Min or (opts.Value and opts.Value.Min) or 0
    local vmax = opts.Max or (opts.Value and opts.Value.Max) or 100
    local vdef = opts.Default or (opts.Value and opts.Value.Default) or vmin
    pcall(function()
        self._t:Slider({
            Title = title,
            Value = { Min = vmin, Max = vmax, Default = vdef },
            Callback = function(v)
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
end

function GroupboxMT:AddDropdown(flag, opts)
    opts = opts or {}
    local vals = opts.Values or opts.Options or {}
    local def = opts.Default
    if type(def) == "number" and vals[def] ~= nil then def = vals[def] end
    local proxy = { Value = def, _items = vals }
    local ok, w = pcall(function()
        return self._t:Dropdown({
            Title = opts.Text or opts.Title or tostring(flag),
            Values = vals, Default = def, Multi = opts.Multi,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    proxy._ok = ok; proxy._w = w
    function proxy.Clear(_)
        proxy._items = {}
        if ok and w then
            pcall(function() w:Refresh({}, true) end)
            pcall(function() w:Clear() end)
        end
    end
    function proxy.Add(_, v)
        table.insert(proxy._items, v)
        if ok and w then
            pcall(function() w:Add(v) end)
            pcall(function() w:Refresh(proxy._items, true) end)
        end
    end
    function proxy.SetOptions(_, list)
        proxy._items = list
        if ok and w then
            pcall(function() w:Refresh(list, true) end)
            pcall(function() w:SetOptions(list) end)
        end
    end
    Library.Options[flag] = proxy
    Library.Toggles[flag] = proxy
    return proxy
end

function GroupboxMT:AddInput(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default or "" }
    pcall(function()
        self._t:Input({
            Title = opts.Text or opts.Title or tostring(flag),
            Default = opts.Default, Placeholder = opts.Placeholder,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddLabel(text)
    pcall(function() self._t:Paragraph({ Title = tostring(text) }) end)
    local lbl = {}
    function lbl.AddKeyPicker(_, kflag, kopts)
        local picker = { Value = kopts and kopts.Default or nil }
        function picker.SetValue(_, v) picker.Value = v end
        Library.Options[kflag] = picker
        return picker
    end
    function lbl.AddColorPicker(_, cflag, copts)
        GroupboxMT.AddColorPicker(self, cflag, copts)
        return lbl
    end
    return lbl
end

function GroupboxMT:AddDivider() pcall(function() self._t:Space({ Columns = 1 }) end) end
function GroupboxMT:AddSpace() pcall(function() self._t:Space({ Columns = 1 }) end) end

function GroupboxMT:AddColorPicker(flag, opts)
    opts = opts or {}
    local proxy = { Value = opts.Default }
    pcall(function()
        self._t:ColorPicker({
            Title = opts.Title or opts.Text or tostring(flag),
            Default = opts.Default,
            Callback = function(v)
                proxy.Value = v
                if opts.Callback then pcall(opts.Callback, v) end
            end,
        })
    end)
    Library.Options[flag] = proxy
    return proxy
end

function GroupboxMT:AddCode(opts)
    opts = opts or {}
    pcall(function() self._t:Paragraph({ Title = tostring(opts.Text or opts.Title or "") }) end)
end
function GroupboxMT:AddImage(opts)
    opts = opts or {}
    pcall(function() self._t:Paragraph({ Title = tostring(opts.Name or opts.Title or "") }) end)
end
function GroupboxMT:AddKeyPicker(flag, opts)
    local p = { Value = opts and opts.Default or nil }
    function p.SetValue(_, v) p.Value = v end
    Library.Options[flag] = p
    return p
end

local Options = Library.Options
local Toggles = Library.Toggles

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local player = Players.LocalPlayer
local Remotes = ReplicatedStorage.Assets.Remotes

local KillAura = {
    Enabled = false,
    Range = 12,
    Cooldown = 0.35,
    LastAttack = 0,
    Connection = nil,
    CurrentTarget = nil
}

local AutoKill = {
    Enabled = false,
    Connection = nil,
    CurrentTarget = nil,
    Blacklist = {},
    AttackCount = {},
    MaxAttempts = 15,
    ShieldCooldown = 17
}

local HIT_PARTS = {
    "Torso", "Head", "HumanoidRootPart",
    "Left Leg", "Right Leg", "Left Arm", "Right Arm"
}

local function IsRealPlayer(model)
    if not model then return false end
    local name = model.Name
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Name == name and p ~= player then
            return true
        end
    end
    return false
end

local function GetNearbyTarget()
    local char = player.Character
    if not char then return nil end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    local charsFolder = workspace:FindFirstChild("Characters")
    if not charsFolder then return nil end
    local bestTarget = nil
    local bestDist = KillAura.Range
    for _, model in ipairs(charsFolder:GetChildren()) do
        if model ~= char then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local targetHrp = model:FindFirstChild("HumanoidRootPart")
            if humanoid and targetHrp and humanoid.Health > 0 and IsRealPlayer(model) then
                local dist = (targetHrp.Position - hrp.Position).Magnitude
                if dist < bestDist then
                    bestDist = dist
                    bestTarget = model
                end
            end
        end
    end
    return bestTarget
end

local function GetHitPart(target)
    for _, name in ipairs(HIT_PARTS) do
        local part = target:FindFirstChild(name)
        if part then return part end
    end
    return target:FindFirstChildWhichIsA("BasePart")
end

local function PlayHitEffects(target)
    local char = player.Character
    if not char then return end
    local tool = char:FindFirstChildOfClass("Tool")
    if not tool then return end
    local success, AudioHandler = pcall(function()
        return require(ReplicatedStorage.Assets.Modules:WaitForChild("AudioHandler"))
    end)
    if success and AudioHandler then
        local torso = target:FindFirstChild("Torso") or target.PrimaryPart
        if torso then
            AudioHandler.playAudio(tool, torso, {type = "hit", pitch = 1}, true, true)
        end
    end
    local success2, Math = pcall(function()
        return require(ReplicatedStorage.Assets.Modules:WaitForChild("Math"))
    end)
    if success2 and Math then
        local controller = _G.WeaponController or getfenv(0).weaponController
        if controller and controller.springs then
            controller.springs.cameraShake:Impulse(Vector3.new(
                Math.Randomize2(-3.08, 3.08, 0.001),
                Math.Randomize2(-1.848, 1.848, 0.001),
                0
            ))
            controller.springs.cameraShakeRot:Impulse(Vector3.new(
                Math.Randomize2(-1.54, 1.54, 0.001),
                0,
                Math.Randomize2(-0.462, 0.462, 0.001)
            ))
        end
    end
end

local function DoAttack()
    if tick() - KillAura.LastAttack < KillAura.Cooldown then return end
    KillAura.LastAttack = tick()
    local char = player.Character
    if not char then return end
    local tool = char:FindFirstChildOfClass("Tool")
    if not tool then return end
    local target = GetNearbyTarget()
    if not target then
        KillAura.CurrentTarget = nil
        return
    end
    KillAura.CurrentTarget = target
    local humanoid = target:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    local hitPart = GetHitPart(target)
    if not hitPart then return end
    Remotes.MeleeHitVerification:FireServer(tool, target:FindFirstChildOfClass("Part"), 1)
    Remotes.meleeHit:FireServer(tool, humanoid, 1, hitPart, "false |none")
    PlayHitEffects(target)
end

local function OnHeartbeat()
    if not KillAura.Enabled then return end
    DoAttack()
end

function KillAura:Toggle(state)
    self.Enabled = state
    if state then
        if self.Connection then return end
        self.Connection = RunService.Heartbeat:Connect(OnHeartbeat)
    else
        if self.Connection then
            self.Connection:Disconnect()
            self.Connection = nil
        end
        self.CurrentTarget = nil
    end
end

local function TeleportToTarget(target)
    local char = player.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local targetHrp = target:FindFirstChild("HumanoidRootPart")
    if not targetHrp then return end
    hrp.CFrame = CFrame.new(targetHrp.Position + Vector3.new(0, -2, 0))
end

local function IsTargetDead(target)
    if not target or not target.Parent then return true end
    local humanoid = target:FindFirstChildOfClass("Humanoid")
    if not humanoid then return true end
    return humanoid.Health <= 0
end

local function GetTargetHealth(target)
    if not target then return 0 end
    local humanoid = target:FindFirstChildOfClass("Humanoid")
    if not humanoid then return 0 end
    return humanoid.Health
end

local function CheckShield(target)
    local name = target.Name
    local currentHealth = GetTargetHealth(target)
    if not AutoKill.AttackCount[name] then
        AutoKill.AttackCount[name] = {count = 0, lastHealth = currentHealth, startTime = tick()}
    end
    local data = AutoKill.AttackCount[name]
    data.count = data.count + 1
    if data.count >= AutoKill.MaxAttempts then
        if currentHealth >= data.lastHealth then
            AutoKill.Blacklist[name] = tick()
            AutoKill.AttackCount[name] = nil
            Library:Notify("该玩家带有无敌护盾已跳到下一位玩家: " .. name, 3)
            return true
        else
            AutoKill.AttackCount[name] = nil
        end
    end
    return false
end

local function IsBlacklisted(name)
    if not AutoKill.Blacklist[name] then return false end
    if tick() - AutoKill.Blacklist[name] >= AutoKill.ShieldCooldown then
        AutoKill.Blacklist[name] = nil
        return false
    end
    return true
end

local function GetAllAliveRealPlayers()
    local char = player.Character
    if not char then return {} end
    local charsFolder = workspace:FindFirstChild("Characters")
    if not charsFolder then return {} end
    local list = {}
    for _, model in ipairs(charsFolder:GetChildren()) do
        if model ~= char then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.Health > 0 and IsRealPlayer(model) then
                table.insert(list, model)
            end
        end
    end
    return list
end

local function HasNonBlacklistedTarget()
    local allPlayers = GetAllAliveRealPlayers()
    for _, model in ipairs(allPlayers) do
        if not IsBlacklisted(model.Name) then
            return true
        end
    end
    return false
end

local function AutoKillLoop()
    if not AutoKill.Enabled then return end
    local char = player.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    if AutoKill.CurrentTarget and not IsTargetDead(AutoKill.CurrentTarget) then
        if CheckShield(AutoKill.CurrentTarget) then
            AutoKill.CurrentTarget = nil
            return
        end
        TeleportToTarget(AutoKill.CurrentTarget)
        return
    end
    AutoKill.CurrentTarget = nil
    local allPlayers = GetAllAliveRealPlayers()
    local bestTarget = nil
    local bestDist = math.huge
    for _, model in ipairs(allPlayers) do
        if not IsBlacklisted(model.Name) then
            local targetHrp = model:FindFirstChild("HumanoidRootPart")
            if targetHrp then
                local dist = (targetHrp.Position - hrp.Position).Magnitude
                if dist < bestDist then
                    bestDist = dist
                    bestTarget = model
                end
            end
        end
    end
    if not bestTarget then
        for _, model in ipairs(allPlayers) do
            if IsBlacklisted(model.Name) then
                local targetHrp = model:FindFirstChild("HumanoidRootPart")
                if targetHrp then
                    local dist = (targetHrp.Position - hrp.Position).Magnitude
                    if dist < bestDist then
                        bestDist = dist
                        bestTarget = model
                    end
                end
            end
        end
    end
    if bestTarget then
        AutoKill.CurrentTarget = bestTarget
        if not AutoKill.AttackCount[bestTarget.Name] then
            AutoKill.AttackCount[bestTarget.Name] = {count = 0, lastHealth = GetTargetHealth(bestTarget), startTime = tick()}
        end
        TeleportToTarget(bestTarget)
    end
end

local function OnAutoKillHeartbeat()
    if not AutoKill.Enabled then return end
    AutoKillLoop()
end

function AutoKill:Toggle(state)
    self.Enabled = state
    if state then
        KillAura:Toggle(true)
        if self.Connection then return end
        self.Connection = RunService.Heartbeat:Connect(OnAutoKillHeartbeat)
    else
        if self.Connection then
            self.Connection:Disconnect()
            self.Connection = nil
        end
        self.CurrentTarget = nil
        self.AttackCount = {}
    end
end

local Window = FakeWindow

Library:Notify("通用血布娃娃战斗 - 创作者：WX HUB", 5)

local Tabs = {
