local KICK_REASON = "你所执行的这个脚本不在这个服务器的使用范围内，所以被踢出"

local function CheckPlaceId(ids)
    if type(ids) == "table" then return ids[game.PlaceId] == true end
    return ids == game.PlaceId
end

-- ==================== 游戏图标解析：PlaceId → UniverseId → 官方游戏图标 ====================
local GameIconCache = {}
local function ResolveGameIcon(gameName)
    if GameIconCache[gameName] ~= nil then return GameIconCache[gameName] end
    local ids = GameIds[gameName]
    if not ids then GameIconCache[gameName] = false return false end
    local placeId = ids
    if type(ids) == "table" then
        placeId = next(ids)
        if not placeId then GameIconCache[gameName] = false return false end
    end
    local icon = false
    pcall(function()
        local raw = game:HttpGet("https://apis.roblox.com/universes/v1/places/" .. tostring(placeId) .. "/universe")
        local okJ, data = pcall(function()
            return game:GetService("HttpService"):JSONDecode(raw)
        end)
        if okJ and type(data) == "table" and data.universeId then
            icon = "rbxthumb://type=GameIcon&id=" .. tostring(data.universeId) .. "&w=150&h=150"
        end
    end)
    GameIconCache[gameName] = icon
    return icon
end

local function PurgeSelector()
    if SelectorPurged then return end
    SelectorPurged = true

    -- 整个自毁流程全程 pcall 双重保险：任何单点失败都不会影响玩家客户端
    pcall(function()
        -- ① 断开选择器注册过的长生命周期全局连接（仅选择器自己的，BS 保护的连接不在这里）
        for _, conn in ipairs(SelectorConnections) do
            pcall(function() conn:Disconnect() end)
        end
        table.clear(SelectorConnections)

        -- ② 销毁选择器创建过的全部 GUI（PlayerGui 下 WXHUB 开头一锅端：
        --    加载器 WXHUBLoader / 游戏列表 WXHUBGameList / 智能弹窗 WXHUB_SmartDetect）
        pcall(function()
            for _, gui in ipairs(playerGui:GetChildren()) do
                if gui.Name:sub(1, 6) == "WXHUB" then
                    pcall(function() gui:Destroy() end)
                end
            end
        end)
        -- 开场动画 GUI 挂在 CoreGui/gethui 下，防御性补一刀
        pcall(function()
            local parent = (gethui and gethui()) or game:GetService("CoreGui")
            for _, gui in ipairs(parent:GetChildren()) do
                if gui.Name == "WXHUB_INTRO" then
                    pcall(function() gui:Destroy() end)
                end
            end
        end)

        -- ③ 停掉开场动画可能残留的背景音乐
        pcall(function()
            local bgm = game:GetService("SoundService"):FindFirstChild("WXHUB_BGM")
            if bgm then bgm:Destroy() end
        end)

        -- ④ 逐个清空选择器占用的全部大表缓存
        --    （游戏脚本源码此刻已取出并编译成 fn，不受影响；每表独立 pcall，互不影响）
        pcall(function() table.clear(GameScripts) end)            -- 最大头：全部游戏脚本源码
        pcall(function() table.clear(GameIds) end)                -- 游戏 PlaceId 映射
        pcall(function() table.clear(LoadServer) end)             -- 服务器列表
        pcall(function() table.clear(Notice) end)                 -- 公告
        pcall(function() table.clear(LoadingSteps) end)           -- 加载步骤
        pcall(function() table.clear(ServerScriptStatus) end)     -- 状态主表
        pcall(function() table.clear(ServerScriptStatusExtra) end)
        pcall(function() table.clear(ServerStatusMap) end)
        pcall(function() table.clear(ServerStatusUserSet) end)
        pcall(function() table.clear(GameIconCache) end)          -- 游戏图标缓存
    end)

    -- ⑤ GC 不再主线程硬 collect（3MB+ 脚本全量回收的内存峰值会卡死/闪退部分设备），
    --    延后一帧温和执行一次即可，清理效果一样且玩家无感知
    task.defer(function()
        pcall(collectgarbage, "collect")
    end)

    print("[WX HUB] 选择器已自毁清理：GUI/连接/缓存全部释放，仅保留 BS 防抓保护。")
end

local function ExecuteGame(gameName)
    -- ===== 服务器脚本状态检测（红=关闭中 黄=维护中，仅对应服务器内生效）=====
    local st = GetServerStatus(gameName)
    if (st == "red" or st == "yellow") and GameIds[gameName] and CheckPlaceId(GameIds[gameName]) then
        player:Kick(SERVER_STATUS_KICK_REASON[st])
        return
    end
    local src = GameScripts[gameName]
    if not src then return end
    local fn = loadstring(src)
    if fn then
        -- 游戏脚本编译成功：先启动游戏脚本，自毁选择器延后一帧执行
        -- （避开按钮事件回调，防止个别执行器在事件派发中拆 GUI 出问题；
        --   游戏 GUI 最快也要等 WindUI 下载完才会创建，晚一帧清场绝对安全）
        task.defer(PurgeSelector)
        task.spawn(fn)
    end
end

-- ==================== 统一关闭加载器/游戏列表 UI ====================
local LoaderUIRefs = { screenGui = nil, mainContainer = nil, background = nil, closed = false }

local function CloseMainUI(instant)
    if LoaderUIRefs.closed then return end
    LoaderUIRefs.closed = true
    local sg = LoaderUIRefs.screenGui
    local mc = LoaderUIRefs.mainContainer
    local bg = LoaderUIRefs.background
    local function destroySG()
        if sg and sg.Parent then sg:Destroy() end
    end
    if instant then
        destroySG()
        return
    end
    if mc and mc.Parent then
        local closeInfo = TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In)
        local scaleTween = TweenService:Create(mc, closeInfo, {
            Size = UDim2.new(0, 0, 0, 0),
            Position = UDim2.new(0.5, 0, 0.5, 0)
        })
        scaleTween:Play()
        if bg and bg.Parent then
            TweenService:Create(bg, closeInfo, { BackgroundTransparency = 1 }):Play()
        end
        scaleTween.Completed:Connect(destroySG)
        task.delay(0.6, destroySG)
    else
        destroySG()
    end
end
