        local itemFired = false
        local function handleGameSelect()
            if itemFired then return end
            itemFired = true
            TweenService:Create(gameItem, TweenInfo.new(0.08), {
                BackgroundColor3 = Color3.fromRGB(139, 92, 246)
            }):Play()
            if not CheckPlaceId(GameIds[gameName]) then
                player:Kick(KICK_REASON)
                return
            end
            CloseMainUI(false)
            ExecuteGame(gameName)
        end
        gameButton.Activated:Connect(handleGameSelect)
        gameButton.MouseButton1Click:Connect(handleGameSelect)
        local pressPos = nil
        gameItem.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                pressPos = input.Position
            end
        end)
        gameItem.InputEnded:Connect(function(input)
            if not pressPos then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                local delta = input.Position - pressPos
                pressPos = nil
                if math.abs(delta.X) < 12 and math.abs(delta.Y) < 12 then
                    handleGameSelect()
                end
            end
        end)

        gameItem.MouseEnter:Connect(function()
            local hoverInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            TweenService:Create(gameItem, hoverInfo, {
                BackgroundColor3 = Color3.fromRGB(37, 22, 60)
